#include "scripts/weapons.gen.hpp"
#include "weapon_data.gen.hpp"
#include "terrain_heights.gen.hpp"  // hitscan vs the ground
#include "controls.hpp"

#include <math.h>

// A controls.hpp the user took ownership of before weapons existed
// carries no bindings - fall back so such a project still builds.
#ifndef BTN_FIRE
#define BTN_FIRE R1
#endif
#ifndef BTN_RELOAD
#define BTN_RELOAD Triangle
#endif
